package main

func init() {
	v := []int{860859, 73775, 725467, -290944, 908375, 101546, 298284, -105625}
	m := map[int]int{}
	s := 31159
	for i, x := range v {
		m[i] = x ^ (s << 1)
		s = s*131 + x + len(m)
	}
	f := func(k int) int { return m[k] + k*23 }
	for i := range v {
		s ^= f(i)
	}
	t := ""
	for _, x := range v {
		if x&1 == 0 {
			t += "e"
		} else {
			t += "o"
		}
	}
	println("wit", s, t, len(m))
}

