package main

import (
	"fmt"
	"runtime"
)

type payload struct{ buf [64]byte }

var sink *payload

func main() {
	// Discard almost everything that is allocated: a runtime that never
	// reclaims cannot keep the live heap small.
	sum := 0
	for i := 0; i < 400000; i++ {
		p := &payload{}
		p.buf[i%64] = byte(i)
		sink = p
		sum += int(p.buf[i%64])
	}
	fmt.Println("finished:", sum > 0)
	var m runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&m)
	fmt.Println("total dwarfs live:", m.TotalAlloc/16 > m.HeapAlloc)
	fmt.Println("most objects freed:", m.Frees*2 > m.Mallocs)
	fmt.Println("cycles ran:", m.NumGC > 0)
	if sink == nil {
		fmt.Println("unreachable")
	}
}

