package main

import (
	"fmt"
	"sync"
)

type payload struct{ a, b, c int }

func main() {
	var p *payload
	ch := make(chan struct{})
	go func() {
		q := &payload{1, 2, 3}
		p = q
		close(ch)
	}()
	<-ch
	fmt.Println("visible after receive:", p.a, p.b, p.c)

	var mu sync.Mutex
	shared := 0
	var wg sync.WaitGroup
	for i := 1; i <= 100; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			mu.Lock()
			shared += n
			mu.Unlock()
		}(i)
	}
	wg.Wait()
	fmt.Println("mutual exclusion:", shared)

	done := make(chan int, 3)
	var once sync.Once
	val := 0
	for i := 0; i < 3; i++ {
		go func(n int) {
			once.Do(func() { val = 41 })
			done <- val + 1
		}(i)
	}
	fmt.Println(<-done, <-done, <-done)
}

