	next *node
}

func build(n int) *node {
	if n == 0 {
		return nil
	}
	return &node{n, build(n - 1)}
}

func sum(p *node) int {
	if p == nil {
		return 0
	}
	return p.v + sum(p.next)
}

func fib(n int) int {
	if n < 2 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

func main() {
	println(sum(build(10)))
	println(fib(20))
	x := new(int)
	*x = 7
	y := &x
	**y = 9
	println(*x)
	arr := [3]int{1, 2, 3}
	pa := &arr
	pa[1] = 5
	println(arr[1], len(pa))
}

