package main

func catch(name string, f func()) {
	defer func() {
		r := recover()
		if r == nil {
			println(name, "no panic")
			return
		}
		println(name, r.(error).Error())
	}()
	f()
}

func main() {
	s := []int{1, 2, 3}
	catch("index", func() { i := 5; _ = s[i] })
	catch("slice", func() { i := 9; _ = s[1:i] })
	var m map[string]int
	catch("nilmap", func() { m["x"] = 1 })
	var p *int
	catch("nilptr", func() { _ = *p })
	catch("divzero", func() { z := 0; _ = 1 / z })
	var i interface{} = "str"
	catch("assert", func() { _ = i.(int) })
	var e interface{}
	catch("nilassert", func() { _ = e.(int) })
}

