import (
	"runtime"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	total := 0
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			runtime.Gosched()
			mu.Lock()
			total += n
			mu.Unlock()
		}(i)
	}
	wg.Wait()
	println("total", total)
	ch := make(chan int)
	var once sync.Once
	for i := 0; i < 3; i++ {
		go func() { once.Do(func() { ch <- 1 }) }()
	}
	println("once", <-ch)
}

