package main

import (
	"errors"
	"fmt"
	"unicode/utf8"
)

var errBase = errors.New("base failure")

func fail(n int) error {
	if n == 0 {
		return nil
	}
	return errBase
}

func main() {
	fmt.Println(fail(0) == nil, fail(1) == errBase, fail(1).Error())
	e2 := errors.New("base failure")
	fmt.Println(e2 == errBase, e2.Error() == errBase.Error())
	s := "héllo, 世界"
	fmt.Println(len(s), utf8.RuneCountInString(s), utf8.ValidString(s))
	r, size := utf8.DecodeRuneInString(s[1:])
	fmt.Println(r, size, string(r))
	buf := make([]byte, 4)
	n := utf8.EncodeRune(buf, '世')
	fmt.Println(n, string(buf[:n]), utf8.RuneLen('世'), utf8.RuneLen('a'))
	bad := string([]byte{0xff, 'a'})
	r2, sz2 := utf8.DecodeRuneInString(bad)
	fmt.Println(r2 == utf8.RuneError, sz2, utf8.ValidString(bad))
}

