package main

type Named int

func kind(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return "nil"
	case int:
		if x > 10 {
			return "bigint"
		}
		return "int"
	case string, bool:
		return "strbool"
	case Named:
		return "named"
	case []int:
		return "slice"
	case error:
		return "error"
	default:
		return "other"
	}
}

type myErr struct{}

func (myErr) Error() string { return "e" }

func main() {
	println(kind(nil), kind(1), kind(99), kind("s"), kind(true))
	println(kind(Named(1)), kind([]int{1}), kind(myErr{}), kind(1.5))
}

